  },
  "goal": [
    {
      "id": "parallel-coord-encoding",
      "insight": "Render a parallel coordinates chart with 8 vertical axes (one per benchmark dimension), where each polyline represents a model, colored by model family (e.g., GPT=blue, Claude=purple, Gemini=green, LLaMA=orange, Qwen=red), with a legend mapping families to colors"
    },
    {
      "id": "reasoning-speed-tradeoff",
      "insight": "Visually emphasize the crossing pattern between the Reasoning axis and the Inference Speed axis, showing that models scoring high on reasoning tend to dip on speed and vice versa"
    },
    {
      "id": "multimodal-math-tradeoff",
      "insight": "Highlight the divergent line trajectories between the Multimodal Understanding axis and the Math/Quantitative axis, drawing attention to models that excel in one but drop in the other"
    },
    {
      "id": "family-cluster-patterns",
      "insight": "Show how polylines of the same model family color tend to cluster together across most axes, revealing family-level capability profiles"
    },
    {
      "id": "top-model-standouts",
      "insight": "Make the top-performing models visually prominent (e.g., thicker or brighter lines) so viewers can quickly identify which models dominate across multiple dimensions"
    }
  ]
}

